css:
.print-format { padding: 0 !important; }
.aliz-dn {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 12px;
    color: #000;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    line-height: 1.35;
}
.aliz-dn table { width: 100%; border-collapse: collapse; }
.aliz-dn td, .aliz-dn th { vertical-align: top; }
.aliz-dn .dn-inner td { border: none; }

/* Header */
.aliz-dn .dn-head td { padding: 0; }
.aliz-dn .dn-logo { width: 50%; }
.aliz-dn .dn-logo img { max-height: 80px; max-width: 220px; }
.aliz-dn .dn-company-name { font-size: 18px; font-weight: bold; }
.aliz-dn .dn-company-address { width: 50%; text-align: right; font-size: 11px; line-height: 1.6; }
.aliz-dn .dn-rule { border-top: 1px solid #000; margin: 14px 0 18px 0; }

/* Title */
.aliz-dn .dn-title {
    width: 74%;
    background: #d9d9d9;
    font-size: 16px;
    font-weight: bold;
    letter-spacing: 0.5px;
    padding: 7px 14px;
    margin-bottom: 18px;
}

/* Ship to / meta box */
.aliz-dn .dn-info { border: 1px solid #000; margin-bottom: 10px; }
.aliz-dn .dn-info > tbody > tr > td,
.aliz-dn .dn-info > tr > td { padding: 14px 14px 12px 14px; }
.aliz-dn .dn-shipto { width: 70%; border-right: 1px solid #000; }
.aliz-dn .dn-shipto-label { width: 70px; white-space: nowrap; font-weight: bold; padding: 0; }
.aliz-dn .dn-shipto-value { padding: 0; }
.aliz-dn .dn-meta-label { width: 92px; white-space: nowrap; font-weight: bold; padding: 0 0 14px 0; }
.aliz-dn .dn-meta-value { padding: 0 0 14px 0; }
.aliz-dn .dn-vehicle { padding: 0; font-size: 11px; }

/* Items */
.aliz-dn .dn-items-wrap { min-height: 400px; }
.aliz-dn .dn-items { border: 1px solid #000; }
.aliz-dn .dn-items th {
    background: #f2f2f2;
    color: #666;
    font-weight: normal;
    text-align: center;
    border: 1px solid #000;
    padding: 8px 6px 10px 6px;
}
.aliz-dn .dn-items td { border: 1px solid #000; padding: 8px 8px; }
.aliz-dn .dn-items th.c-sl { text-align: left; }
.aliz-dn .c-sl { width: 6%; }
.aliz-dn .c-part { width: 16%; }
.aliz-dn .c-desc { width: 39%; text-align: left; }
.aliz-dn .c-pallet { width: 10%; text-align: center; }
.aliz-dn .c-unit { width: 8%; text-align: center; }
.aliz-dn .c-qty { width: 8%; text-align: center; }
.aliz-dn .c-wt { width: 11%; text-align: right; }
.aliz-dn .dn-items th.c-wt { text-align: center; }
.aliz-dn .dn-items tr { page-break-inside: avoid; }

/* Received by / totals */
.aliz-dn .dn-foot { border: 1px solid #000; page-break-inside: avoid; }
.aliz-dn .dn-recv { width: 50%; border-right: 1px solid #000; padding: 10px 8px 12px 8px; font-weight: bold; font-size: 11px; }
.aliz-dn .dn-recv-title { margin-bottom: 12px; }
.aliz-dn .dn-recv-line { margin-bottom: 11px; }
.aliz-dn .dn-recv-line span { font-weight: normal; }
.aliz-dn .dn-totals { width: 50%; padding: 12px 16px 8px 16px; }
.aliz-dn .dn-tot-label { font-weight: bold; font-size: 11px; padding: 0 0 18px 0; }
.aliz-dn .dn-tot-value { font-weight: bold; font-size: 11px; text-align: right; padding: 0 0 18px 0; }

/* Signatures */
.aliz-dn .dn-sign { margin-top: 22px; page-break-inside: avoid; }
.aliz-dn .dn-sign td { font-weight: bold; font-size: 11px; padding: 0; }
.aliz-dn .dn-sign td.dn-sign-left { width: 45%; padding-left: 8px; }
.aliz-dn .dn-sign-gap { width: 10%; }
.aliz-dn .dn-sign-right { width: 45%; text-align: right; }
.aliz-dn .dn-sign-line { border-top: 1px solid #000; margin-bottom: 10px; }
.aliz-dn .dn-sign-left .dn-sign-line { margin-left: -8px; }
.aliz-dn .dn-sign-right .dn-sign-line { margin-right: -8px; }
.aliz-dn .dn-sign td.dn-sign-right { padding-right: 8px; }
